using System.Security.Cryptography;
using System.Text.RegularExpressions;

namespace Hexagon.Database.Bootstrap;

/// <summary>Database passwords generated by the maintenance tasks: random, alphanumeric and never logged.</summary>
internal static class Credential
{
    private const string Alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";

    public static string Generate() => RandomNumberGenerator.GetString(Alphabet, 40);

    /// <summary>The bounded alphabet lets the password appear in an ALTER ROLE statement without escaping.</summary>
    public static bool IsValid(string value) => Regex.IsMatch(value, "^[A-Za-z0-9]{32,128}$");
}
